def pass_at_k(n, c, k):
    if n - c < k:
        return 1.0
    return 1 - math.comb(n - c, k) / math.comb(n, k)

def cohen_kappa(human, judge):
    n = len(human)
    po = sum(h == j for h, j in zip(human, judge)) / n
    pe = sum((human.count(l) / n) * (judge.count(l) / n) for l in set(human) | set(judge))
    return (po - pe) / (1 - pe)
